<template>
  <div><PageHeader eyebrow="ESSAY" title="Tiểu luận" description="Quản lý đề tài canonical, nhóm và file submission theo đúng validation của assignment."><template #actions><button v-if="canManage" class="button primary" @click="showForm = !showForm">{{ showForm ? 'Đóng biểu mẫu' : 'Tạo assignment' }}</button></template></PageHeader><div v-if="error" class="error-banner"><span>{{ error }}</span><button class="mini-button" @click="loadClasses">Thử lại</button></div>
    <section v-if="showForm" class="panel" style="margin-bottom:16px"><form class="grid-two" @submit.prevent="createAssignment"><div class="form-field"><label>Lớp học</label><select v-model="form.classId" class="form-select" required><option value="">Chọn lớp</option><option v-for="item in classes" :key="item.id" :value="item.id">{{ item.code }} · {{ item.name }}</option></select></div><div class="form-field"><label>Tiêu đề</label><input v-model.trim="form.title" class="form-input" required /></div><div class="form-field"><label>Hạn nộp</label><input v-model="form.deadline" class="form-input" type="datetime-local" /></div><div class="form-field"><label>Điểm tối đa / cỡ nhóm</label><div style="display:flex;gap:8px"><input v-model.number="form.maxScore" class="form-input" type="number" min="1" required /><input v-model.number="form.maxGroupSize" class="form-input" type="number" min="1" required /></div></div><div class="form-field"><label>Mô tả</label><textarea v-model.trim="form.description" class="form-textarea"></textarea></div><button class="button primary" :disabled="busy">Tạo assignment</button></form></section>
    <div class="toolbar"><select v-model="selectedClassId" class="form-select" style="max-width:320px"><option value="">Chọn lớp học</option><option v-for="item in classes" :key="item.id" :value="item.id">{{ item.code }} · {{ item.name }}</option></select><span class="cell-subtle">{{ assignments.length }} assignment</span></div>
    <div v-if="loading" class="loading-state">Đang tải tiểu luận…</div><template v-else-if="selectedClassId"><div class="cards-grid"><article v-for="assignment in assignments" :key="assignment.id" class="activity-card"><div class="card-topline"><span class="code-label">{{ assignment.maxScore }} ĐIỂM</span><StatusPill :value="assignment.status" /></div><h3>{{ assignment.title }}</h3><p>{{ assignment.description || 'Assignment tiểu luận theo nhóm.' }}</p><div class="card-footer"><span class="card-meta">{{ assignment.deadline ? `Hạn ${formatDate(assignment.deadline)}` : 'Chưa đặt hạn' }}</span><div class="card-actions"><button class="mini-button" @click="selectAssignment(assignment)">{{ selectedAssignment?.id === assignment.id ? 'Đang mở' : 'Mở chi tiết' }}</button><button v-if="canManage && isAssignmentPublished(assignment.status)" class="mini-button" @click="closeAssignment(assignment)">Đóng</button></div></div></article></div><div v-if="selectedAssignment" class="grid-two" style="margin-top:16px"><section class="panel"><div class="panel-heading"><h2>{{ selectedAssignment.title }}</h2><span>{{ groups.length }} nhóm</span></div><div class="page-actions"><button v-if="canManage" class="mini-button" @click="publishAssignment">Publish assignment</button><button v-if="auth.role === 'student' || canManage" class="mini-button" @click="createGroup">Tạo nhóm</button></div><div class="list-compact"><div v-for="group in groups" :key="group.id" class="list-compact-item"><div><strong>{{ group.name || `Nhóm ${group.id.slice(0, 6)}` }}</strong><span>{{ memberCount(group) }} thành viên · {{ topicLabel(group) }}</span></div><button class="mini-button" @click="selectGroup(group)">{{ selectedGroup?.id === group.id ? 'Đang mở' : 'Mở nhóm' }}</button></div></div><div v-if="!groups.length" class="empty-state"><strong>Chưa có nhóm</strong><span>Nhóm được tạo từ flow assignment.</span></div></section><section class="panel"><div v-if="selectedGroup"><div class="panel-heading"><h2>{{ selectedGroup.name }}</h2><StatusPill :value="selectedGroup.status" /></div><div class="stack"><div class="list-compact-item"><div><strong>Đề tài</strong><span>{{ topic?.canonicalTitle || topic?.proposedTitle || 'Chưa đăng ký đề tài' }}</span></div><StatusPill :value="topic?.status || 'Chưa có'" /></div><div class="list-compact-item"><div><strong>Thành viên</strong><span>{{ selectedGroup.members?.map(member => member.displayName || member.studentId.slice(0, 8)).join(' · ') || selectedGroup.memberIds?.map(id => id.slice(0, 8)).join(' · ') || 'Chưa có thành viên' }}</span></div><form class="inline-form" @submit.prevent="addGroupMember"><input v-model.trim="memberId" class="form-input" required placeholder="Student ID" /><button class="mini-button" :disabled="busy">Thêm</button></form></div><div v-if="topic && canManage" class="page-actions"><button class="mini-button" @click="reviewTopic('approve')">Approve</button><button class="mini-button" @click="reviewTopic('changes')">Request change</button><button class="mini-button" @click="reviewTopic('reject')">Reject</button><button v-if="String(topic.status).toLowerCase().includes('approv')" class="mini-button" @click="reviewTopic('lock')">Lock canonical</button></div><form v-if="!topic && auth.role === 'student'" class="inline-form" @submit.prevent="registerTopic"><div class="form-field"><label>Đề xuất đề tài</label><input v-model.trim="topicTitle" class="form-input" required placeholder="Canonical topic sẽ được teacher duyệt" /></div><button class="button primary">Đăng ký</button></form><form v-if="topic && auth.role === 'student' && !isTopicLocked(topic.status)" class="inline-form" @submit.prevent="requestTopicChange"><div class="form-field"><label>Đề xuất đổi đề tài</label><input v-model.trim="topicChangeTitle" class="form-input" required placeholder="Tên đề tài mới" /></div><button class="button secondary">Xin đổi đề tài</button></form><div class="panel-heading" style="margin-top:16px"><h2>Submission</h2><span>{{ submissions.length }}</span></div><div v-if="submissions.length" class="list-compact"><div v-for="submission in submissions" :key="submission.id" class="list-compact-item"><div><strong>Version {{ submission.version }}</strong><span>{{ submission.fileName || 'File đã tải lên' }} · {{ formatDateTime(submission.submittedAt || submission.uploadedAt) }}</span><span v-if="submission.errors?.length" class="cell-subtle">{{ submission.errors.join(' · ') }}</span></div><div class="card-actions"><StatusPill :value="submission.validationStatus || submission.status" /><button class="mini-button" @click="openSubmissionFile(submission)">Mở báo cáo</button><button v-if="canManage" class="mini-button" @click="selectedSubmission = submission">Chấm</button></div></div></div><div v-else class="empty-state"><strong>Chưa có submission</strong><span>File PDF/DOCX sẽ được backend kiểm tra trước khi tạo final submission.</span></div><label v-if="auth.role === 'student'" class="button secondary" style="margin-top:12px">Chọn file<input type="file" hidden accept=".pdf,.docx,application/pdf,application/vnd.openxmlformats-officedocument.wordprocessingml.document" @change="upload" /></label><span v-if="uploadState" class="cell-subtle">{{ uploadState }}</span><form v-if="selectedSubmission && canManage" class="panel" style="margin-top:14px" @submit.prevent="gradeSelected"><div class="panel-heading"><h2>Teacher grading · v{{ selectedSubmission.version }}</h2><button type="button" class="mini-button" @click="selectedSubmission = null">Đóng</button></div><div class="grid-two"><div class="form-field"><label>Điểm</label><input v-model.number="gradeForm.score" class="form-input" type="number" min="0" :max="selectedAssignment.maxScore" required /></div><div class="form-field"><label>Feedback</label><input v-model.trim="gradeForm.feedback" class="form-input" placeholder="Nhận xét của teacher" /></div></div><div class="page-actions" style="margin-top:12px"><button class="button primary" :disabled="grading">Lưu điểm</button><button v-if="selectedSubmission.gradeEntryId" type="button" class="button secondary" @click="publishSelected">Publish result</button></div></form></div></div><div v-else class="empty-state"><strong>Chọn một nhóm</strong><span>Chi tiết đề tài và submission chỉ tải cho nhóm đang mở.</span></div></section></div></template><div v-else class="panel empty-state"><strong>Chọn lớp học</strong><span>Chọn lớp để xem assignment tiểu luận theo quyền của bạn.</span></div>
  </div>
</template>
<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'; import PageHeader from '../../../shared/ui/PageHeader.vue'; import StatusPill from '../../../shared/ui/StatusPill.vue'; import { useAuthStore } from '../../../shared/stores/auth'; import { academicsApi, essayApi } from '../../../shared/api/client'; import { formatDate, formatDateTime, type EssayAssignment, type EssayGroup, type EssaySubmission, type EssayTopic, type LearningClass } from '../../../shared/types'
const auth = useAuthStore(); const selectedSubmission = ref<EssaySubmission | null>(null); const gradeForm = reactive({ score: 0, feedback: '' }); const grading = ref(false); const classes = ref<LearningClass[]>([]); const selectedClassId = ref(''); const assignments = ref<EssayAssignment[]>([]); const selectedAssignment = ref<EssayAssignment | null>(null); const groups = ref<EssayGroup[]>([]); const selectedGroup = ref<EssayGroup | null>(null); const topic = ref<EssayTopic | null>(null); const submissions = ref<EssaySubmission[]>([]); const topicTitle = ref(''); const topicChangeTitle = ref(''); const memberId = ref(''); const loading = ref(true); const busy = ref(false); const error = ref(''); const showForm = ref(false); const uploadState = ref(''); const form = reactive({ classId: '', title: '', description: '', deadline: '', maxScore: 100, maxGroupSize: 4 }); const canManage = computed(() => auth.has('assessment.activities.manage'))
const names = computed(() => new Map(classes.value.map(item => [item.id, `${item.code} · ${item.name}`]))); function memberCount(group: EssayGroup) { return group.members?.length ?? group.memberIds?.length ?? 0 }; function topicLabel(group: EssayGroup) { return group.topicId ? 'Đã đăng ký đề tài' : 'Chưa có đề tài' }; function isAssignmentPublished(status: string | number) { return status === 1 || String(status).toLowerCase() === 'published' }; function isTopicLocked(status: string | number) { return status === 5 || String(status).toLowerCase() === 'locked' }
async function loadClasses() { loading.value = true; try { classes.value = await academicsApi.classes(); if (!selectedClassId.value && classes.value[0]) selectedClassId.value = classes.value[0].id } catch (cause) { error.value = String((cause as Error)?.message || 'Không tải được lớp học.') } finally { loading.value = false } }
async function loadAssignments() { if (!selectedClassId.value) { assignments.value = []; return }; loading.value = true; try { assignments.value = await essayApi.assignments(selectedClassId.value); selectedAssignment.value = null; groups.value = [] } catch (cause) { error.value = String((cause as Error)?.message || 'Không tải được assignment.') } finally { loading.value = false } }
async function createAssignment() { if (!form.classId) return; busy.value = true; try { const assignment = await essayApi.createAssignment(form.classId, { title: form.title, description: form.description, deadline: form.deadline || undefined, maxScore: form.maxScore, maxGroupSize: form.maxGroupSize, allowResubmission: true }); assignments.value.unshift(assignment); showForm.value = false; form.title = ''; form.description = ''; form.deadline = '' } catch (cause) { error.value = String((cause as Error)?.message || 'Không tạo được assignment.') } finally { busy.value = false } }
async function selectAssignment(item: EssayAssignment) { selectedAssignment.value = item; selectedGroup.value = null; topic.value = null; submissions.value = []; try { groups.value = await essayApi.groups(item.id) } catch (cause) { error.value = String((cause as Error)?.message || 'Không tải được nhóm.') } }
async function publishAssignment() { if (!selectedAssignment.value) return; try { const updated = await essayApi.publishAssignment(selectedAssignment.value.id); selectedAssignment.value = updated; const index = assignments.value.findIndex(item => item.id === updated.id); if (index >= 0) assignments.value[index] = updated } catch (cause) { error.value = String((cause as Error)?.message || 'Không publish được assignment.') } }
async function closeAssignment(assignment: EssayAssignment) { if (!window.confirm('Đóng assignment này?')) return; try { const updated = await essayApi.closeAssignment(assignment.id); Object.assign(assignment, updated); if (selectedAssignment.value?.id === assignment.id) selectedAssignment.value = updated } catch (cause) { error.value = String((cause as Error)?.message || 'Không đóng được assignment.') } }
async function createGroup() { if (!selectedAssignment.value) return; try { const group = await essayApi.createGroup(selectedAssignment.value.id, `Nhóm ${groups.value.length + 1}`); groups.value.push(group) } catch (cause) { error.value = String((cause as Error)?.message || 'Không tạo được nhóm.') } }
async function selectGroup(group: EssayGroup) { selectedGroup.value = group; topic.value = null; submissions.value = []; const result = await Promise.allSettled([essayApi.topic(group.id), essayApi.submissions(group.id)]); if (result[0].status === 'fulfilled') topic.value = result[0].value; if (result[1].status === 'fulfilled') submissions.value = result[1].value }
async function addGroupMember() { if (!selectedGroup.value || !memberId.value) return; busy.value = true; try { const updated = await essayApi.addMember(selectedGroup.value.id, memberId.value); selectedGroup.value = updated; const index = groups.value.findIndex(item => item.id === updated.id); if (index >= 0) groups.value[index] = updated; memberId.value = '' } catch (cause) { error.value = String((cause as Error)?.message || 'Không thêm được thành viên.') } finally { busy.value = false } }
async function registerTopic() { if (!selectedGroup.value) return; try { topic.value = await essayApi.registerTopic(selectedGroup.value.id, topicTitle.value); topicTitle.value = '' } catch (cause) { error.value = String((cause as Error)?.message || 'Không đăng ký được đề tài.') } }
async function requestTopicChange() { if (!topic.value || !topicChangeTitle.value) return; try { topic.value = await essayApi.requestTopicChange(topic.value.essayGroupId, topicChangeTitle.value); topicChangeTitle.value = '' } catch (cause) { error.value = String((cause as Error)?.message || 'Không gửi được yêu cầu đổi đề tài.') } }
async function reviewTopic(action: 'approve' | 'changes' | 'reject' | 'lock') { if (!topic.value) return; try { topic.value = action === 'approve' ? await essayApi.approveTopic(topic.value.id) : action === 'changes' ? await essayApi.requestTopicChanges(topic.value.id) : action === 'reject' ? await essayApi.rejectTopic(topic.value.id) : await essayApi.lockTopic(topic.value.id) } catch (cause) { error.value = String((cause as Error)?.message || 'Không cập nhật được đề tài.') } }
async function gradeSelected() { if (!selectedSubmission.value) return; grading.value = true; try { const result = await essayApi.gradeSubmission(selectedSubmission.value.id, gradeForm.score, gradeForm.feedback) as { id: string; score?: number; feedback?: string }; selectedSubmission.value.gradeEntryId = result.id; selectedSubmission.value.score = gradeForm.score; selectedSubmission.value.feedback = gradeForm.feedback } catch (cause) { error.value = String((cause as Error)?.message || 'Không lưu được điểm.') } finally { grading.value = false } }
async function publishSelected() { if (!selectedSubmission.value?.gradeEntryId) return; try { await essayApi.publishGrade(selectedSubmission.value.gradeEntryId); selectedSubmission.value.status = 'Graded' } catch (cause) { error.value = String((cause as Error)?.message || 'Không publish được điểm.') } }
async function openSubmissionFile(submission: EssaySubmission) { const popup = window.open('about:blank', '_blank'); try { const file = await essayApi.submissionFile(submission.id); if (popup) popup.location.href = file.accessUrl; else window.location.href = file.accessUrl } catch (cause) { popup?.close(); error.value = String((cause as Error)?.message || 'Không mở được báo cáo.') } }
async function upload(event: Event) { const file = (event.target as HTMLInputElement).files?.[0]; if (!file || !selectedAssignment.value || !selectedGroup.value) return; uploadState.value = 'Đang tải và kiểm tra file…'; try { const result = await essayApi.uploadSubmission(selectedAssignment.value.id, selectedGroup.value.id, file); submissions.value.unshift(result); uploadState.value = result.validationMessage || 'File đã được tiếp nhận.' } catch (cause) { uploadState.value = String((cause as Error)?.message || 'Upload thất bại.'); error.value = uploadState.value } }
watch(selectedClassId, value => { form.classId = value; loadAssignments() }); onMounted(loadClasses)
</script>
